CREATE OR REPLACE FUNCTION public.accept_quote(p_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update projects
  set status = 'accepted', accepted_at = now()
  where quote_token = p_token and status in ('draft', 'sent');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_job_number_on_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  approved_stages text[] := array['quote_approved','deposit_paid','ready_to_book','job_booked','job_not_complete','client_handover','awaiting_payment'];
  next_job int;
begin
  if new.job_number is null and new.pipeline_stage = any(approved_stages) then
    update company_settings set next_job_number = next_job_number + 1
      where id = 1
      returning next_job_number - 1 into next_job;
    new.job_number := next_job;
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.book_callback_slot(p_date date, p_time time without time zone, p_name text, p_phone text, p_email text, p_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_max_per_slot int := 2;
  v_open time := '08:00';
  v_close time := '17:00';
  v_booked int;
  v_id uuid;
begin
  if extract(isodow from p_date) not between 1 and 5 then
    return jsonb_build_object('ok', false, 'error', 'Weekends aren''t bookable, please pick a weekday.');
  end if;
  if p_date < current_date then
    return jsonb_build_object('ok', false, 'error', 'That date has passed, please pick another.');
  end if;
  if p_time < v_open or p_time >= v_close then
    return jsonb_build_object('ok', false, 'error', 'Outside business hours (8am-5pm).');
  end if;
  if coalesce(trim(p_phone), '') = '' then
    return jsonb_build_object('ok', false, 'error', 'A phone number is required.');
  end if;
  -- a phone number is digits plus the usual + ( ) - and spaces, 8 digits or more
  -- (a name typed into the phone box used to be accepted and saved as the number)
  if trim(p_phone) !~ '^[0-9+()\s-]{8,20}$' or length(regexp_replace(p_phone, '\D', '', 'g')) < 8 then
    return jsonb_build_object('ok', false, 'error', 'That doesn''t look like a phone number, please check it.');
  end if;

  perform pg_advisory_xact_lock(hashtext(p_date::text || p_time::text));

  select count(*) into v_booked
  from public.callback_requests
  where requested_date = p_date
    and requested_time = p_time
    and status <> 'cancelled';

  if v_booked >= v_max_per_slot then
    return jsonb_build_object('ok', false, 'error', 'That slot just filled up, please pick another.');
  end if;

  insert into public.callback_requests (name, phone, email, requested_date, requested_time, message)
  values (nullif(trim(p_name), ''), trim(p_phone), nullif(trim(p_email), ''), p_date, p_time, nullif(trim(p_message), ''))
  returning id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_balance_due(p_labour numeric, p_material numeric, p_stc numeric)
 RETURNS numeric
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select calculate_balance_due(p_labour, p_material, p_stc, 'individual');
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_balance_due(p_labour numeric, p_material numeric, p_stc numeric, p_client_type text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  subtotal numeric;
  gst numeric;
begin
  subtotal := coalesce(p_labour, 0) + coalesce(p_material, 0);
  gst := round(subtotal * 0.10, 2);
  return subtotal + gst - stc_credit_inc_gst(p_stc, p_client_type);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_bill_due_date(p_bill_date date, p_credit_terms_type text, p_credit_terms_days integer)
 RETURNS date
 LANGUAGE plpgsql
AS $function$
begin
  if p_bill_date is null then
    return null;
  end if;
  if p_credit_terms_type = 'cod' then
    return p_bill_date;
  elsif p_credit_terms_type = 'eom_days' then
    return (date_trunc('month', p_bill_date) + interval '1 month - 1 day')::date + p_credit_terms_days;
  else
    return p_bill_date + p_credit_terms_days;
  end if;
end;
$function$
;

