CREATE OR REPLACE FUNCTION public.classify_timesheet_rate_category(p_clock_in timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  local_ts timestamp; -- AT TIME ZONE on a timestamptz returns plain timestamp
                       -- (naive local wall-clock) - declaring this as
                       -- timestamptz would silently cast it back using the
                       -- session timezone, reintroducing the exact bug
                       -- this conversion exists to avoid.
  local_date date;
  local_time time;
  dow int;
begin
  local_ts := p_clock_in AT TIME ZONE 'Australia/Sydney';
  local_date := local_ts::date;
  local_time := local_ts::time;
  dow := extract(isodow from local_date); -- Monday=1 ... Sunday=7

  if exists (select 1 from public_holidays where holiday_date = local_date) then
    return '2.5x';
  end if;

  if dow = 7 then -- Sunday
    return '2x';
  end if;

  if dow = 6 then -- Saturday
    return '1.5x';
  end if;

  -- Weekday, outside 6:30am-4:00pm
  if local_time < time '06:30:00' or local_time >= time '16:00:00' then
    return '1.5x';
  end if;

  return 'ordinary';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.compute_overhead_rates()
 RETURNS TABLE(direct_total numeric, direct_rate numeric, indirect_total numeric, indirect_rate numeric, billable_hours numeric, oncost_lines numeric, nonbillable_people_cost numeric, company_total numeric, company_pct numeric, company_basis text, mode text, timesheet_days integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s overhead_settings%rowtype;
  v_dir numeric; v_ind numeric; v_hours numeric; v_nbp numeric; v_oc numeric; v_co numeric; v_first timestamptz;
begin
  select * into s from overhead_settings where id = 1;
  select coalesce(sum(c.direct_total), 0), coalesce(sum(c.indirect_total), 0), coalesce(sum(c.billable_hours), 0),
         coalesce(sum(c.indirect_total) filter (where not c.billable or c.billable_hours = 0), 0)
    into v_dir, v_ind, v_hours, v_nbp from overhead_people_calc() c;
  select coalesce(sum(l.annual_amount) filter (where l.bucket = 'employee'), 0), coalesce(sum(l.annual_amount) filter (where l.bucket = 'company'), 0)
    into v_oc, v_co from overhead_lines l;
  select min(t.clock_in) into v_first from time_entries t where t.clock_out is not null and t.clock_in >= now() - interval '12 months';
  return query select
    round(v_dir, 2),
    case when v_hours > 0 then round(v_dir / v_hours, 2) else 0::numeric end,
    round(v_ind, 2),
    case when v_hours > 0 then round(v_ind / v_hours, 2) else 0::numeric end,
    round(v_hours, 1), v_oc, round(v_nbp, 2),
    v_co,
    case when s.expected_annual_base > 0 then round(v_co / s.expected_annual_base * 100, 2) else 0::numeric end,
    s.company_basis, s.hours_mode,
    case when v_first is null then 0 else (now()::date - v_first::date) end;
end $function$
;

CREATE OR REPLACE FUNCTION public.create_notification(p_user uuid, p_kind text, p_title text, p_body text, p_link text, p_actor uuid, p_dedupe text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_user is null or p_user = p_actor then return; end if;
  if not exists (select 1 from profiles where id = p_user and active) then return; end if;
  if (select notification_prefs ->> p_kind from profiles where id = p_user) = 'false' then return; end if;
  insert into notifications (user_id, kind, title, body, link, actor_id, dedupe_key)
  values (p_user, p_kind, left(p_title, 200), left(p_body, 300), p_link, p_actor, p_dedupe)
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
end $function$
;

