 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select role from profiles where id = auth.uid();
$function$
;

CREATE OR REPLACE FUNCTION public.easter_sunday(p_year integer)
 RETURNS date
 LANGUAGE plpgsql
AS $function$
declare
  a int; b int; c int; d int; e int; f int; g int; h int; i int; k int; l int; m int; month int; day int;
begin
  a := p_year % 19;
  b := p_year / 100;
  c := p_year % 100;
  d := b / 4;
  e := b % 4;
  f := (b + 8) / 25;
  g := (b - f + 1) / 3;
  h := (19 * a + b - d - g + 15) % 30;
  i := c / 4;
  k := c % 4;
  l := (32 + 2 * e + 2 * i - h - k) % 7;
  m := (a + 11 * h + 22 * l) / 451;
  month := (h + l - 7 * m + 114) / 31;
  day := ((h + l - 7 * m + 114) % 31) + 1;
  return make_date(p_year, month, day);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_nsw_public_holidays(p_year integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  easter date;
  d date;
  dow int;
  christmas_shift date;
  boxing_shift date;
begin
  -- New Year's Day - additional day if it falls on a weekend
  d := make_date(p_year, 1, 1);
  insert into public_holidays (holiday_date, name) values (d, 'New Year''s Day') on conflict (holiday_date) do nothing;
  dow := extract(isodow from d);
  if dow in (6, 7) then
    insert into public_holidays (holiday_date, name)
    values (d + (8 - dow), 'New Year''s Day (additional day)')
    on conflict (holiday_date) do nothing;
  end if;

  -- Australia Day - shifts to the following Monday if it falls on a weekend
  d := make_date(p_year, 1, 26);
  dow := extract(isodow from d);
  if dow in (6, 7) then
    insert into public_holidays (holiday_date, name) values (d + (8 - dow), 'Australia Day') on conflict (holiday_date) do nothing;
  else
    insert into public_holidays (holiday_date, name) values (d, 'Australia Day') on conflict (holiday_date) do nothing;
  end if;

  -- Easter weekend - Good Friday through Easter Monday
  easter := easter_sunday(p_year);
  insert into public_holidays (holiday_date, name) values (easter - 2, 'Good Friday') on conflict (holiday_date) do nothing;
  insert into public_holidays (holiday_date, name) values (easter - 1, 'Easter Saturday') on conflict (holiday_date) do nothing;
  insert into public_holidays (holiday_date, name) values (easter, 'Easter Sunday') on conflict (holiday_date) do nothing;
  insert into public_holidays (holiday_date, name) values (easter + 1, 'Easter Monday') on conflict (holiday_date) do nothing;

  -- Anzac Day - additional day if it falls on a weekend
  d := make_date(p_year, 4, 25);
  insert into public_holidays (holiday_date, name) values (d, 'Anzac Day') on conflict (holiday_date) do nothing;
  dow := extract(isodow from d);
  if dow in (6, 7) then
    insert into public_holidays (holiday_date, name)
    values (d + (8 - dow), 'Anzac Day (additional day)')
    on conflict (holiday_date) do nothing;
  end if;

  -- King's Birthday - 2nd Monday in June
  d := make_date(p_year, 6, 1);
  d := d + ((8 - extract(isodow from d)::int) % 7) + 7;
  insert into public_holidays (holiday_date, name) values (d, 'King''s Birthday') on conflict (holiday_date) do nothing;

  -- Labour Day - 1st Monday in October
  d := make_date(p_year, 10, 1);
  d := d + ((8 - extract(isodow from d)::int) % 7);
  insert into public_holidays (holiday_date, name) values (d, 'Labour Day') on conflict (holiday_date) do nothing;

  -- Christmas Day - additional day if it falls on a weekend. Computed
  -- first since Boxing Day's own shift (below) needs to know whether
  -- Christmas already claimed the same makeup day, and defer one day
  -- further if so - verified against real NSW government data for 2026
  -- and 2027, where this exact collision genuinely happens.
  d := make_date(p_year, 12, 25);
  insert into public_holidays (holiday_date, name) values (d, 'Christmas Day') on conflict (holiday_date) do nothing;
  dow := extract(isodow from d);
  christmas_shift := null;
  if dow in (6, 7) then
    christmas_shift := d + (8 - dow);
    insert into public_holidays (holiday_date, name)
    values (christmas_shift, 'Christmas Day (additional day)')
    on conflict (holiday_date) do nothing;
  end if;

  -- Boxing Day - additional day if it falls on a weekend, deferred one
  -- further day if that would otherwise land on the same date as
  -- Christmas's own additional day.
  d := make_date(p_year, 12, 26);
  insert into public_holidays (holiday_date, name) values (d, 'Boxing Day') on conflict (holiday_date) do nothing;
  dow := extract(isodow from d);
  if dow in (6, 7) then
    boxing_shift := d + (8 - dow);
    if christmas_shift is not null and boxing_shift = christmas_shift then
      boxing_shift := boxing_shift + 1;
    end if;
    insert into public_holidays (holiday_date, name)
    values (boxing_shift, 'Boxing Day (additional day)')
    on conflict (holiday_date) do nothing;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_active_clock_ins(p_project_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(entry_id uuid, staff_id uuid, full_name text, project_id uuid, project_name text, job_number integer, quote_number integer, time_category text, clock_in timestamp with time zone, stage_names text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    te.id,
    te.staff_id,
    pr.full_name,
    te.project_id,
    p.name,
    p.job_number,
    p.quote_number,
    te.time_category,
    te.clock_in,
    (select array_agg(cc.name order by cc.sort_order)
       from cost_centres cc
      where cc.id = te.cost_centre_id or cc.id = any(coalesce(te.selected_cost_centre_ids, '{}'::uuid[])))
  from time_entries te
  left join profiles pr on pr.id = te.staff_id
  left join projects p on p.id = te.project_id
  where te.clock_out is null
    and auth.uid() is not null
    and (p_project_id is null or te.project_id = p_project_id)
  order by pr.full_name;
$function$
;

CREATE OR REPLACE FUNCTION public.get_available_callback_slots(p_start_date date, p_end_date date)
 RETURNS TABLE(slot_date date, slot_time time without time zone, spots_left integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_slot_minutes int := 30;
  v_max_per_slot int := 2;
  v_open time := '08:00';
  v_close time := '17:00';
  v_day date;
  v_time time;
  v_booked int;
begin
  if p_end_date < p_start_date or p_end_date - p_start_date > 30 then
    raise exception 'Invalid date range';
  end if;

  v_day := p_start_date;
  while v_day <= p_end_date loop
    if extract(isodow from v_day) between 1 and 5 then
      v_time := v_open;
      while v_time < v_close loop
        select count(*) into v_booked
        from public.callback_requests
        where requested_date = v_day
          and requested_time = v_time
          and status <> 'cancelled';

        if v_max_per_slot - v_booked > 0 then
          slot_date := v_day;
          slot_time := v_time;
          spots_left := v_max_per_slot - v_booked;
          return next;
        end if;

        v_time := v_time + (v_slot_minutes || ' minutes')::interval;
      end loop;
    end if;
    v_day := v_day + 1;
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_invoice_balance_due(p_invoice_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  inv record;
  credited record;
begin
  select labour_amount, material_amount, stc_amount
  into inv
  from invoices
  where id = p_invoice_id;

  if not found then
    raise exception 'Invoice % not found', p_invoice_id;
  end if;

  select coalesce(sum(cnc.labour_amount), 0) as labour,
         coalesce(sum(cnc.material_amount), 0) as material,
         coalesce(sum(cnc.stc_amount), 0) as stc
  into credited
  from credit_note_claims cnc
  join credit_notes cn on cn.id = cnc.credit_note_id
  where cn.invoice_id = p_invoice_id;

  return calculate_balance_due(
    inv.labour_amount - credited.labour,
    inv.material_amount - credited.material,
    inv.stc_amount - credited.stc,
    invoice_client_type(p_invoice_id)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_invoice_by_token(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  result jsonb;
begin
  select jsonb_build_object(
    'cost_centre', to_jsonb(cc) - 'xero_invoice_id' - 'xero_invoice_status',
    'project', jsonb_build_object(
      'name', p.name, 'job_number', p.job_number, 'client_name', p.client_name,
      'client_address', p.client_address, 'client_email', p.client_email
    ),
    'company', to_jsonb(cs)
  )
  into result
  from cost_centres cc
  join projects p on p.id = cc.project_id
  cross join company_settings cs
  where cc.invoice_token = p_token and cs.id = 1;

  return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_invoice_by_token_v2(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  result jsonb;
begin
  -- Job-linked invoice - full itemized breakdown + claim history, as before.
  select jsonb_build_object(
    'invoice', (to_jsonb(inv) - 'xero_invoice_id' - 'xero_invoice_status' - 'created_by')
      || jsonb_build_object('balance_due', calculate_balance_due(inv.labour_amount, inv.material_amount, inv.stc_amount)),
    'cost_centre', jsonb_build_object('id', cc.id, 'name', cc.name, 'quoted_amount', cc.quoted_amount, 'stc_total', cc.stc_total),
    'project', jsonb_build_object(
      'name', p.name, 'job_number', p.job_number, 'client_name', p.client_name,
      'client_address', p.client_address, 'client_email', p.client_email
    ),
    'client', jsonb_build_object('client_type', cl.client_type),
    'line_items', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'description', li.description, 'quantity', li.quantity, 'unit_cost', li.unit_cost, 'sort_order', li.sort_order
      ) order by li.sort_order), '[]'::jsonb)
      from cost_centre_line_items li where li.cost_centre_id = cc.id
    ),
    'company', to_jsonb(cs),
    'previous_claims', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'invoice_number', i2.invoice_number, 'labour_amount', i2.labour_amount,
        'material_amount', i2.material_amount, 'stc_amount', i2.stc_amount, 'sent_at', i2.sent_at
      ) order by i2.sent_at), '[]'::jsonb)
      from invoices i2 where i2.cost_centre_id = cc.id and i2.sent_at < inv.sent_at
    )
  )
  into result
  from invoices inv
  join cost_centres cc on cc.id = inv.cost_centre_id
  join projects p on p.id = cc.project_id
  left join clients cl on cl.id = p.client_id
  cross join company_settings cs
  where inv.invoice_token = p_token and inv.cost_centre_id is not null and cs.id = 1;

  if result is not null then
    return result;
  end if;

  -- Standalone invoice - no stage, no job, no claim history. Client comes
  -- straight from invoices.client_id instead of via a project.
  select jsonb_build_object(
    'invoice', (to_jsonb(inv) - 'xero_invoice_id' - 'xero_invoice_status' - 'created_by')
      || jsonb_build_object('balance_due', calculate_balance_due(inv.labour_amount, inv.material_amount, inv.stc_amount)),
    'cost_centre', jsonb_build_object('name', coalesce(inv.description, 'Invoice'), 'quoted_amount', null, 'stc_total', 0),
    'project', jsonb_build_object(
      'name', null, 'job_number', null, 'client_name', cl.name,
      'client_address', cl.address, 'client_email', cl.email
    ),
    'client', jsonb_build_object('client_type', cl.client_type),
    'line_items', '[]'::jsonb,
    'company', to_jsonb(cs),
    'previous_claims', '[]'::jsonb
  )
  into result
  from invoices inv
  left join clients cl on cl.id = inv.client_id
  cross join company_settings cs
  where inv.invoice_token = p_token and inv.cost_centre_id is null and cs.id = 1;

  return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_invoice_by_token_v3(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_invoice invoices%rowtype;
  v_company jsonb;
  v_project jsonb;
  v_claims jsonb := '[]'::jsonb;
  v_previous jsonb := '[]'::jsonb;
  v_balance numeric;
  v_is_standalone boolean;
  v_project_id uuid;
  v_client_type text;
begin
  select * into v_invoice from invoices where invoice_token = p_token;
  if not found then
    return null;
  end if;

  select get_invoice_balance_due(v_invoice.id) into v_balance;
  v_client_type := invoice_client_type(v_invoice.id);
  select to_jsonb(cs) - 'id' into v_company from company_settings cs where id = 1;

  v_is_standalone := v_invoice.project_id is null and v_invoice.cost_centre_id is null;
  v_project_id := coalesce(v_invoice.project_id, (select cc.project_id from cost_centres cc where cc.id = v_invoice.cost_centre_id));

  if not v_is_standalone then
    select jsonb_build_object(
      'job_number', p.job_number,
      'quote_number', p.quote_number,
      'name', p.name,
      'client_name', p.client_name,
      'client_address', p.client_address,
      'client_email', p.client_email,
      'proposal_template', p.proposal_template
    ) into v_project
    from projects p where p.id = v_project_id;
  else
    select jsonb_build_object('client_name', c.name, 'client_address', c.address, 'client_email', c.email)
    into v_project
    from clients c where c.id = v_invoice.client_id;
  end if;

  if exists (select 1 from invoice_claims ic where ic.invoice_id = v_invoice.id) then
    select jsonb_agg(jsonb_build_object(
      'cost_centre_id', cc.id,
      'cost_centre_name', cc.name,
      'quoted_amount', cc.quoted_amount,
      'stc_total', coalesce(cc.stc_total, 0),
      'labour_amount', ic.labour_amount,
      'material_amount', ic.material_amount,
      'stc_amount', ic.stc_amount,
      'claimed_before', coalesce((
        select sum(x.amt) from (
          select ic2.labour_amount + ic2.material_amount as amt
          from invoice_claims ic2 join invoices i2 on i2.id = ic2.invoice_id
          where ic2.cost_centre_id = cc.id and i2.id <> v_invoice.id and i2.created_at < v_invoice.created_at
          union all
          select i3.labour_amount + i3.material_amount
          from invoices i3
          where i3.cost_centre_id = cc.id and i3.id <> v_invoice.id and i3.created_at < v_invoice.created_at
            and not exists (select 1 from invoice_claims ic3 where ic3.invoice_id = i3.id)
          union all
          select -(cnc.labour_amount + cnc.material_amount)
          from credit_note_claims cnc join credit_notes cn on cn.id = cnc.credit_note_id
          where cnc.cost_centre_id = cc.id and cn.created_at < v_invoice.created_at
        ) x
      ), 0),
      'line_items', coalesce((
        select jsonb_agg(jsonb_build_object('description', li.description, 'quantity', li.quantity, 'unit_cost', li.unit_cost) order by li.sort_order)
        from cost_centre_line_items li where li.cost_centre_id = cc.id
      ), '[]'::jsonb),
      'invoice_items', coalesce((
        select jsonb_agg(jsonb_build_object(
          'kind', ili.kind, 'description', ili.description, 'quantity', ili.quantity,
          'unit_price', ili.unit_price, 'labour_amount', ili.labour_amount, 'material_amount', ili.material_amount
        ) order by ili.sort_order, ili.created_at)
        from invoice_line_items ili where ili.invoice_claim_id = ic.id
      ), '[]'::jsonb)
    ) order by cc.sort_order)
    into v_claims
    from invoice_claims ic join cost_centres cc on cc.id = ic.cost_centre_id
    where ic.invoice_id = v_invoice.id;
  elsif v_invoice.cost_centre_id is not null then
    select jsonb_build_array(jsonb_build_object(
      'cost_centre_id', cc.id,
      'cost_centre_name', cc.name,
      'quoted_amount', cc.quoted_amount,
      'stc_total', coalesce(cc.stc_total, 0),
      'labour_amount', v_invoice.labour_amount,
      'material_amount', v_invoice.material_amount,
      'stc_amount', v_invoice.stc_amount,
      'claimed_before', coalesce((
        select sum(i3.labour_amount + i3.material_amount)
        from invoices i3
        where i3.cost_centre_id = cc.id and i3.id <> v_invoice.id and i3.created_at < v_invoice.created_at
      ), 0) - coalesce((
        select sum(cnc.labour_amount + cnc.material_amount)
        from credit_note_claims cnc join credit_notes cn on cn.id = cnc.credit_note_id
        where cnc.cost_centre_id = cc.id and cn.created_at < v_invoice.created_at
      ), 0),
      'line_items', coalesce((
        select jsonb_agg(jsonb_build_object('description', li.description, 'quantity', li.quantity, 'unit_cost', li.unit_cost) order by li.sort_order)
        from cost_centre_line_items li where li.cost_centre_id = cc.id
      ), '[]'::jsonb),
      'invoice_items', '[]'::jsonb
    ))
    into v_claims
    from cost_centres cc where cc.id = v_invoice.cost_centre_id;
  end if;

  if not v_is_standalone then
    select coalesce(jsonb_agg(jsonb_build_object(
      'invoice_number', i.invoice_number,
      'sent_at', i.sent_at,
      'amount', i.labour_amount + i.material_amount
    ) order by i.sent_at), '[]'::jsonb)
    into v_previous
    from invoices i
    where i.id <> v_invoice.id
      and coalesce(i.project_id, (select cc.project_id from cost_centres cc where cc.id = i.cost_centre_id)) = v_project_id
      and i.created_at < v_invoice.created_at;
  end if;

  return jsonb_build_object(
    'invoice', to_jsonb(v_invoice) || jsonb_build_object(
      'balance_due', v_balance,
      'client_type', v_client_type,
      'stc_credit_inc_gst', stc_credit_inc_gst(v_invoice.stc_amount, v_client_type)
    ),
    'project', v_project,
    'company', v_company,
    'is_standalone', v_is_standalone,
    'claims', v_claims,
    'previous_invoices', v_previous
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_monthly_net_summary(p_months integer DEFAULT 12)
 RETURNS TABLE(month date, revenue numeric, materials numeric, job_labour numeric, gross_profit numeric, direct_overheads numeric, indirect_wages numeric, company_costs numeric, net_profit numeric, job_hours numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dir numeric; v_nbp numeric; v_co numeric;
begin
  if not is_finance_role() then return; end if;
  select cr.direct_total, cr.nonbillable_people_cost, cr.company_total into v_dir, v_nbp, v_co from compute_overhead_rates() cr;
  return query
  with months as (
    select generate_series(date_trunc('month', now() at time zone 'Australia/Sydney')::date - ((greatest(1, least(p_months, 24)) - 1) || ' months')::interval,
                           date_trunc('month', now() at time zone 'Australia/Sydney')::date, interval '1 month')::date as m),
  rev as (
    select date_trunc('month', i.sent_at at time zone 'Australia/Sydney')::date as m, sum(coalesce(i.labour_amount, 0) + coalesce(i.material_amount, 0)) as v
    from invoices i where i.sent_at is not null group by 1),
  mat as (
    select date_trunc('month', li.received_at at time zone 'Australia/Sydney')::date as m, sum(li.quantity * li.unit_cost) as v
    from purchase_order_line_items li where li.received and li.received_at is not null group by 1),
  tm as (
    select date_trunc('month', t.clock_in at time zone 'Australia/Sydney')::date as m,
      sum(case when t.time_category = 'job' then h.hrs else 0 end) as job_hours,
      sum(case when t.time_category = 'job' then h.hrs * coalesce(p.ordinary_rate, 0) else 0 end) as job_wages,
      sum(case when t.time_category not in ('job', 'training', 'tafe') and coalesce(op.billable, p.role in ('staff', 'sales')) then h.hrs * coalesce(p.ordinary_rate, 0) else 0 end) as nonjob_wages
    from time_entries t
    join profiles p on p.id = t.staff_id
    left join overhead_people op on op.profile_id = p.id
    cross join lateral (select extract(epoch from (t.clock_out - t.clock_in)) / 3600.0 - coalesce(t.break_minutes, 0) / 60.0 as hrs) h
    where t.clock_out is not null group by 1)
  select mo.m,
    round(coalesce(rev.v, 0), 2), round(coalesce(mat.v, 0), 2), round(coalesce(tm.job_wages, 0), 2),
    round(coalesce(rev.v, 0) - coalesce(mat.v, 0) - coalesce(tm.job_wages, 0), 2),
    round(v_dir / 12.0, 2),
    round(coalesce(tm.nonjob_wages, 0) + v_nbp / 12.0, 2),
    round(v_co / 12.0, 2),
    round(coalesce(rev.v, 0) - coalesce(mat.v, 0) - coalesce(tm.job_wages, 0) - v_dir / 12.0 - coalesce(tm.nonjob_wages, 0) - v_nbp / 12.0 - v_co / 12.0, 2),
    round(coalesce(tm.job_hours, 0), 2)
  from months mo left join rev on rev.m = mo.m left join mat on mat.m = mo.m left join tm on tm.m = mo.m
  order by mo.m desc;
end $function$
;

CREATE OR REPLACE FUNCTION public.get_next_number(counter_name text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  next_val int;
begin
  if not is_pricing_role() then
    raise exception 'Not authorized';
  end if;

  if counter_name = 'quote' then
    update company_settings set next_quote_number = next_quote_number + 1
      where id = 1 returning next_quote_number - 1 into next_val;
  elsif counter_name = 'job' then
    update company_settings set next_job_number = next_job_number + 1
      where id = 1 returning next_job_number - 1 into next_val;
  elsif counter_name = 'invoice' then
    update company_settings set next_invoice_number = next_invoice_number + 1
      where id = 1 returning next_invoice_number - 1 into next_val;
  elsif counter_name = 'po' then
    update company_settings set next_po_number = next_po_number + 1
      where id = 1 returning next_po_number - 1 into next_val;
  else
    raise exception 'Unknown counter: %', counter_name;
  end if;

  return next_val;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_next_number_serverside(counter_name text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  next_val int;
begin
  if counter_name = 'quote' then
    update company_settings set next_quote_number = next_quote_number + 1
      where id = 1 returning next_quote_number - 1 into next_val;
  elsif counter_name = 'job' then
    update company_settings set next_job_number = next_job_number + 1
      where id = 1 returning next_job_number - 1 into next_val;
  elsif counter_name = 'invoice' then
    update company_settings set next_invoice_number = next_invoice_number + 1
      where id = 1 returning next_invoice_number - 1 into next_val;
  elsif counter_name = 'po' then
    update company_settings set next_po_number = next_po_number + 1
      where id = 1 returning next_po_number - 1 into next_val;
  else
    raise exception 'Unknown counter: %', counter_name;
  end if;

  return next_val;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_nonbillable_cost_by_category(p_start date, p_end date)
 RETURNS TABLE(category text, total_hours numeric, total_cost numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  return query
  select
    te.time_category,
    coalesce(sum(extract(epoch from (te.clock_out - te.clock_in)) / 3600.0), 0) as total_hours,
    coalesce(sum(
      (extract(epoch from (te.clock_out - te.clock_in)) / 3600.0) *
      case classify_timesheet_rate_category(te.clock_in)
        when '2.5x' then coalesce(p.rate_2_5x, p.ordinary_rate, 0)
        when '2x' then coalesce(p.rate_2x, p.ordinary_rate, 0)
        when '1.5x' then coalesce(p.rate_1_5x, p.ordinary_rate, 0)
        else coalesce(p.ordinary_rate, 0)
      end
    ), 0) as total_cost
  from time_entries te
  join profiles p on p.id = te.staff_id
  where te.time_category != 'job'
    and te.clock_out is not null
    and (te.clock_in AT TIME ZONE 'Australia/Sydney')::date between p_start and p_end
  group by te.time_category;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_overhead_people(p_mode text DEFAULT NULL::text)
 RETURNS TABLE(profile_id uuid, full_name text, role text, billable boolean, subcontractor boolean, days_per_week numeric, hours_per_day numeric, paid_hours numeric, leave_hours numeric, training_hours numeric, nonbillable_hours numeric, billable_hours numeric, hourly_cost numeric, wages numeric, oncosts numeric, direct_total numeric, direct_rate numeric, indirect_total numeric, cost_per_billable_hour numeric, from_timesheets boolean, logged_hours numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_finance_role() then return; end if;
  return query select * from overhead_people_calc(p_mode) c order by c.full_name;
end $function$
;

CREATE OR REPLACE FUNCTION public.get_overhead_rates()
 RETURNS TABLE(direct_total numeric, direct_rate numeric, indirect_total numeric, indirect_rate numeric, billable_hours numeric, oncost_lines numeric, nonbillable_people_cost numeric, company_total numeric, company_pct numeric, company_basis text, mode text, timesheet_days integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_finance_role() then return; end if;
  return query select * from compute_overhead_rates();
end $function$
;

CREATE OR REPLACE FUNCTION public.get_project_overheads(p_project_id uuid)
 RETURNS TABLE(est_rate numeric, actual_amount numeric, actual_hours numeric, company_pct numeric, company_basis text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cr record;
begin
  if not is_finance_role() then return; end if;
  select * into cr from compute_overhead_rates();
  return query
  with hrs as (
    select t.staff_id, sum(greatest(0, extract(epoch from (t.clock_out - t.clock_in)) / 3600.0 - coalesce(t.break_minutes, 0) / 60.0)) as h
    from time_entries t
    where t.project_id = p_project_id and t.clock_out is not null and t.time_category = 'job'
    group by t.staff_id)
  select cr.direct_rate + cr.indirect_rate,
    round(coalesce(sum(hrs.h * (coalesce(c.direct_rate, cr.direct_rate) + cr.indirect_rate)), 0), 2),
    round(coalesce(sum(hrs.h), 0), 2),
    cr.company_pct, cr.company_basis
  from hrs left join overhead_people_calc() c on c.profile_id = hrs.staff_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.get_quote_by_token(p_token text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  result json;
begin
  select json_build_object(
    'project', row_to_json(p),
    'client_type', coalesce((select cl.client_type from clients cl where cl.id = p.client_id), 'individual'),
    'prepared_by', (select pr.full_name from profiles pr where pr.id = p.created_by),
    'cost_centres', (
      select coalesce(json_agg(
        json_build_object(
          'id', c.id,
          'name', c.name,
          'description', c.description,
          'sort_order', c.sort_order,
          'quoted_amount', c.quoted_amount,
          'stc_total', c.stc_total,
          'is_variation', (c.variation_entry_id is not null),
          'variation_reason', ve.reason,
          'photo_groups', (
            select coalesce(json_agg(
              json_build_object('description', g.description, 'photos', g.photos)
              order by g.sort_order
            ), '[]'::json)
            from cost_centre_photo_groups g
            where g.cost_centre_id = c.id
          ),
          'line_items', (
            select coalesce(json_agg(
              json_build_object('description', li.description, 'amount', li.amount, 'quantity', li.quantity, 'item_type', li.item_type)
              order by li.sort_order
            ), '[]'::json)
            from (
              select cli.description as description,
                (case when cli.item_type = 'labour' then cli.quantity * cli.unit_cost
                      else cli.quantity * cli.unit_cost * (1 + coalesce(c.markup_percent, 45) / 100.0)
                 end) as amount,
                cli.quantity as quantity,
                cli.item_type as item_type,
                cli.sort_order as sort_order
              from cost_centre_line_items cli
              where cli.cost_centre_id = c.id and cli.prebuild_group_id is null

              union all

              select max(cli.prebuild_client_description) as description,
                sum(case when cli.item_type = 'labour' then cli.quantity * cli.unit_cost
                         else cli.quantity * cli.unit_cost * (1 + coalesce(c.markup_percent, 45) / 100.0)
                    end) as amount,
                (array_agg(cli.quantity / nullif(cli.prebuild_base_quantity, 0) order by cli.sort_order))[1] as quantity,
                null::text as item_type,
                min(cli.sort_order) as sort_order
              from cost_centre_line_items cli
              where cli.cost_centre_id = c.id and cli.prebuild_group_id is not null
              group by cli.prebuild_group_id
            ) li
          )
        ) order by c.sort_order
      ), '[]'::json)
      from cost_centres c
      left join job_variation_entries ve on ve.id = c.variation_entry_id
      where c.project_id = p.id
        and (c.variation_entry_id is null or (ve.variation_type = 'fixed' and ve.approval_status = 'approved'))
    ),
    'payment_milestones', (
      select coalesce(json_agg(
        json_build_object('label', m.label, 'percent', m.percent)
        order by m.sort_order
      ), '[]'::json)
      from payment_milestones m where m.project_id = p.id
    ),
    'schedule_of_rates', (
      case when p.proposal_template = 'quick_estimate' then (
        select coalesce(json_agg(
          json_build_object('name', t.name, 'sell_rate', t.sell_rate)
          order by t.sort_order
        ), '[]'::json)
        from billable_rate_tiers t
      ) else null end
    )
  ) into result
  from projects p
  where p.quote_token = p_token;

  return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_stage_actual_hours(p_cost_centre_id uuid)
 RETURNS numeric
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select coalesce(sum(extract(epoch from (clock_out - clock_in)) / 3600.0), 0)
  from time_entries
  where cost_centre_id = p_cost_centre_id and clock_out is not null;
$function$
;

CREATE OR REPLACE FUNCTION public.get_stage_actual_labour_cost(p_cost_centre_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  shift_cost numeric := 0;
  allowance_cost numeric := 0;
begin
  select coalesce(sum(
    (extract(epoch from (te.clock_out - te.clock_in)) / 3600.0) *
    case classify_timesheet_rate_category(te.clock_in)
      when '2.5x' then coalesce(p.rate_2_5x, p.ordinary_rate, 0)
      when '2x' then coalesce(p.rate_2x, p.ordinary_rate, 0)
      when '1.5x' then coalesce(p.rate_1_5x, p.ordinary_rate, 0)
      else coalesce(p.ordinary_rate, 0)
    end
  ), 0)
  into shift_cost
  from time_entries te
  join profiles p on p.id = te.staff_id
  where te.cost_centre_id = p_cost_centre_id
    and te.clock_out is not null;

  -- Allowances: for each employee-day that touched this stage, apportion
  -- their per-day allowances by (hours on this stage / hours that day
  -- across all stages). Per-hour allowances just apply to the hours
  -- actually logged on this stage directly - no apportionment needed.
  select coalesce(sum(
    case ea.frequency
      when 'per_day' then ea.amount * (stage_hours.hrs / day_hours.total_hrs)
      when 'per_hour' then ea.amount * stage_hours.hrs
      else 0
    end
  ), 0)
  into allowance_cost
  from (
    select te.staff_id, (te.clock_in AT TIME ZONE 'Australia/Sydney')::date as work_date,
      sum(extract(epoch from (te.clock_out - te.clock_in)) / 3600.0) as hrs
    from time_entries te
    where te.cost_centre_id = p_cost_centre_id and te.clock_out is not null
    group by te.staff_id, (te.clock_in AT TIME ZONE 'Australia/Sydney')::date
  ) stage_hours
  join (
    select te.staff_id, (te.clock_in AT TIME ZONE 'Australia/Sydney')::date as work_date,
      sum(extract(epoch from (te.clock_out - te.clock_in)) / 3600.0) as total_hrs
    from time_entries te
    where te.clock_out is not null
    group by te.staff_id, (te.clock_in AT TIME ZONE 'Australia/Sydney')::date
  ) day_hours on day_hours.staff_id = stage_hours.staff_id and day_hours.work_date = stage_hours.work_date
  join employee_allowances ea on ea.profile_id = stage_hours.staff_id
  where day_hours.total_hrs > 0;

  return shift_cost + allowance_cost;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_stage_actual_material_cost(p_cost_centre_id uuid)
 RETURNS numeric
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select coalesce(sum(quantity * unit_cost), 0)
  from job_material_usage
  where cost_centre_id = p_cost_centre_id;
$function$
;

CREATE OR REPLACE FUNCTION public.get_supplier_financial_summary(p_supplier_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(supplier_id uuid, invoiced_not_paid numeric, approved_for_payment numeric, not_approved numeric, overdue numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  return query
  select
    sb.supplier_id,
    coalesce(sum(case when not sb.paid then sb.amount else 0 end), 0) as invoiced_not_paid,
    coalesce(sum(case when not sb.paid and sb.approved_for_payment then sb.amount else 0 end), 0) as approved_for_payment,
    coalesce(sum(case when not sb.paid and not sb.approved_for_payment then sb.amount else 0 end), 0) as not_approved,
    coalesce(sum(case when not sb.paid and sb.due_date is not null and sb.due_date < current_date then sb.amount else 0 end), 0) as overdue
  from supplier_bills sb
  where (p_supplier_id is null or sb.supplier_id = p_supplier_id)
    and sb.supplier_id is not null
  group by sb.supplier_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_variation_by_token(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ve job_variation_entries%rowtype;
  p projects%rowtype;
  src_token text;
begin
  select * into ve from job_variation_entries
  where variation_token = p_token and variation_type = 'fixed' and approval_status in ('sent', 'approved', 'declined');
  if not found then
    return null;
  end if;
  select * into p from projects where id = ve.project_id;
  select coalesce((select s.quote_token from projects s where s.id = p.source_quote_id), p.quote_token) into src_token;

  return jsonb_build_object(
    'variation', jsonb_build_object(
      'id', ve.id, 'number', ve.variation_number, 'description', ve.description, 'reason', ve.reason,
      'lines', ve.fixed_lines, 'approval_status', ve.approval_status, 'sent_at', ve.sent_at,
      'approved_at', ve.approved_at, 'signed_by_name', ve.signed_by_name,
      'signature_data_url', case when ve.approval_status = 'approved' then ve.signature_data_url else null end,
      'job_number', p.job_number, 'job_name', p.name, 'client_name', p.client_name
    ),
    'quote', get_quote_by_token(src_token)::jsonb,
    'other_variations', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'number', o.variation_number, 'description', o.description, 'reason', o.reason,
        'lines', o.fixed_lines, 'approved_at', o.approved_at
      ) order by o.variation_number), '[]'::jsonb)
      from job_variation_entries o
      where o.project_id = ve.project_id and o.variation_type = 'fixed' and o.approval_status = 'approved' and o.id <> ve.id
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_profiles_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    return new;
  end if;

  if is_admin() then
    return new;
  end if;

  if current_profile_role() = 'finance' and old.id <> auth.uid() then
    if (to_jsonb(new) - 'job_title') is distinct from (to_jsonb(old) - 'job_title') then
      raise exception 'Finance can only update job_title on another employee''s profile.';
    end if;
    return new;
  end if;

  if new.role is distinct from old.role
    or new.active is distinct from old.active
    or new.ordinary_rate is distinct from old.ordinary_rate
    or new.rate_1_5x is distinct from old.rate_1_5x
    or new.rate_2x is distinct from old.rate_2x
    or new.rate_2_5x is distinct from old.rate_2_5x
    or new.annual_salary is distinct from old.annual_salary
    or new.rate_tier_id is distinct from old.rate_tier_id
    or new.employment_type is distinct from old.employment_type
    or new.pay_type is distinct from old.pay_type
    or new.employment_start_date is distinct from old.employment_start_date
  then
    raise exception 'Only an admin can change role, active status, pay rates, or employment classification.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.invoice_client_type(p_invoice_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select cl.client_type
       from invoices i
       left join cost_centres cc on cc.id = i.cost_centre_id
       left join projects p on p.id = coalesce(i.project_id, cc.project_id)
       left join clients cl on cl.id = coalesce(i.client_id, p.client_id)
      where i.id = p_invoice_id),
    'individual');
$function$
;

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select coalesce((select role from profiles where id = auth.uid()) = 'admin', false);
$function$
;

CREATE OR REPLACE FUNCTION public.is_finance_role()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select coalesce((select role from profiles where id = auth.uid()) in ('admin', 'finance'), false);
$function$
;

CREATE OR REPLACE FUNCTION public.is_pricing_role()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select coalesce((select role from profiles where id = auth.uid()) in ('admin', 'finance', 'sales'), false);
$function$
;

CREATE OR REPLACE FUNCTION public.job_tasks_spawn_next_occurrence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  next_due date;
begin
  if new.completed = true and coalesce(old.completed, false) = false
     and new.recurrence is not null and new.due_date is not null then
    next_due := case new.recurrence
      when 'daily' then new.due_date + interval '1 day'
      when 'weekly' then new.due_date + interval '7 days'
      when 'monthly' then new.due_date + interval '1 month'
    end;
    insert into job_tasks (
      project_id, description, assigned_to_user_id, assigned_to_role,
      required_before_scheduling, task_type, due_date, recurrence, created_by
    ) values (
      new.project_id, new.description, new.assigned_to_user_id, new.assigned_to_role,
      new.required_before_scheduling, new.task_type, next_due, new.recurrence, new.created_by
    );
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.notif_job_label(p_project uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when job_number is not null then 'J' || job_number || ' - ' || name
              when quote_number is not null then 'Q' || quote_number || ' - ' || name
              else name end
  from projects where id = p_project
$function$
;

CREATE OR REPLACE FUNCTION public.overhead_people_calc(p_mode text DEFAULT NULL::text)
 RETURNS TABLE(profile_id uuid, full_name text, role text, billable boolean, subcontractor boolean, days_per_week numeric, hours_per_day numeric, paid_hours numeric, leave_hours numeric, training_hours numeric, nonbillable_hours numeric, billable_hours numeric, hourly_cost numeric, wages numeric, oncosts numeric, direct_total numeric, direct_rate numeric, indirect_total numeric, cost_per_billable_hour numeric, from_timesheets boolean, logged_hours numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s overhead_settings%rowtype;
  v_mode text;
  v_oncost_lines numeric;
begin
  select * into s from overhead_settings where id = 1;
  v_mode := coalesce(p_mode, s.hours_mode);
  select coalesce(sum(l.annual_amount), 0) into v_oncost_lines from overhead_lines l where l.bucket = 'employee';
  return query
  with ts as (
    select t.staff_id,
      sum(x.h) as all_h,
      sum(case when t.time_category in ('training', 'tafe') then x.h else 0 end) as train_h,
      sum(case when t.time_category in ('job', 'training', 'tafe') then 0 else x.h end) as admin_h
    from time_entries t
    cross join lateral (select greatest(0, extract(epoch from (t.clock_out - t.clock_in)) / 3600.0 - coalesce(t.break_minutes, 0) / 60.0) as h) x
    where t.clock_out is not null and t.clock_in >= now() - interval '12 months'
    group by t.staff_id),
  base as (
    select p.id as pid, p.full_name as pname, p.role as prole,
      coalesce(op.billable, p.role in ('staff', 'sales')) as is_billable,
      coalesce(op.subcontractor, false) as is_sc,
      coalesce(op.days_per_week, s.default_days_per_week) as dpw,
      coalesce(op.hours_per_day, s.default_hours_per_day) as hpd,
      coalesce(op.nonbillable_hours_per_day, s.default_nonbillable_hours_per_day) as nbpd,
      coalesce(op.annual_leave_days, s.default_annual_leave_days * least(coalesce(op.days_per_week, s.default_days_per_week), 5) / 5.0) as al,
      coalesce(op.sick_days, s.default_sick_days * least(coalesce(op.days_per_week, s.default_days_per_week), 5) / 5.0) as sl,
      coalesce(op.training_days, s.default_training_days) as td,
      coalesce(op.other_costs_per_year, 0) as other,
      coalesce(p.ordinary_rate, 0) as rate,
      coalesce(p.annual_salary, 0) as salary,
      coalesce(ts.all_h, 0) as all_h, coalesce(ts.train_h, 0) as train_h, coalesce(ts.admin_h, 0) as admin_h
    from profiles p
    left join overhead_people op on op.profile_id = p.id
    left join ts on ts.staff_id = p.id
    where p.active),
  d as (
    select b.*,
      52 * b.dpw * b.hpd as paid_h,
      case when b.is_sc or b.dpw = 0 then 0 else s.public_holidays_per_year * least(b.dpw, 5) / 5.0 + b.al + b.sl end as leave_d,
      case when b.is_sc or b.dpw = 0 then 0 else b.al end as annual_d,
      case when b.is_sc or b.dpw = 0 then 0 else b.td end as train_d,
      (v_mode = 'timesheets' and b.all_h >= 40) as use_ts
    from base b),
  e as (
    select d.*,
      greatest(0, 52 * d.dpw - d.leave_d - d.train_d) as work_d,
      case when d.salary > 0 and d.paid_h > 0 then d.salary / d.paid_h else d.rate end as hr,
      case when d.salary > 0 then d.salary else d.paid_h * d.rate end as wage
    from d),
  f as (
    select e.*,
      e.work_d * e.hpd as avail_h,
      least(e.work_d * e.hpd, case when e.use_ts then e.work_d * e.hpd * e.admin_h / e.all_h else e.work_d * e.nbpd end) as nb_h,
      case when e.use_ts then e.work_d * e.hpd * e.train_h / e.all_h else 0 end as ts_train_h
    from e),
  w as (select coalesce(sum(f.wage) filter (where not f.is_sc), 0) as all_wages from f),
  g as (
    select f.*,
      case when f.is_billable then greatest(0, f.avail_h - f.nb_h - f.ts_train_h) else 0 end as bill_h,
      case when f.is_sc then f.other else
        f.wage * (s.super_pct + s.workers_comp_pct + s.payroll_tax_pct) / 100.0
        + f.annual_d * f.hpd * f.hr * s.leave_loading_pct / 100.0
        + case when w.all_wages > 0 then v_oncost_lines * f.wage / w.all_wages else 0 end
        + f.other end as oc
    from f cross join w),
  r as (
    select g.*,
      case when g.is_billable and g.bill_h > 0 then (g.leave_d * g.hpd + g.train_d * g.hpd + g.ts_train_h) * g.hr + g.oc else 0 end as dir,
      case when g.is_billable and g.bill_h > 0 then g.nb_h * g.hr else g.wage + g.oc end as ind
    from g)
  select r.pid, r.pname, r.prole, r.is_billable, r.is_sc, r.dpw, r.hpd,
    round(r.paid_h, 1), round(r.leave_d * r.hpd, 1), round(r.train_d * r.hpd + r.ts_train_h, 1), round(r.nb_h, 1), round(r.bill_h, 1),
    round(r.hr, 2), round(r.wage, 2), round(r.oc, 2),
    round(r.dir, 2),
    case when r.bill_h > 0 then round(r.dir / r.bill_h, 2) end,
    round(r.ind, 2),
    case when r.bill_h > 0 then round(r.hr + r.dir / r.bill_h, 2) end,
    r.use_ts, round(r.all_h, 1)
  from r;
end $function$
;

CREATE OR REPLACE FUNCTION public.send_hr_letter(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w staff_warnings;
begin
  if not is_finance_role() then raise exception 'Only admin or finance can send letters'; end if;
  select * into w from staff_warnings where id = p_id;
  if w.id is null then raise exception 'Letter not found'; end if;
  if w.status = 'draft' then raise exception 'Sign and issue the letter before sending it'; end if;
  update staff_warnings set sent_to_employee_at = coalesce(sent_to_employee_at, now()) where id = p_id;
  perform create_notification(
    w.profile_id, 'hr_letter',
    case when w.status = 'resolved' then 'Good news: a matter on your file has been resolved'
         when w.letter_type = 'counselling' then 'A letter from management to read and sign'
         else 'A written warning to read and sign' end,
    case when w.status = 'resolved' then 'Open it to read the resolution letter.'
         else 'Please read it, add any comments, and sign to confirm you have received it.' end,
    '/letter.html?id=' || p_id, auth.uid(), 'hr_letter:' || p_id || ':' || w.status);
end $function$
;

CREATE OR REPLACE FUNCTION public.sign_hr_letter(p_id uuid, p_signature text, p_name text, p_comments text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w staff_warnings;
begin
  select * into w from staff_warnings where id = p_id;
  if w.id is null or w.profile_id <> auth.uid() or w.sent_to_employee_at is null then raise exception 'Letter not found'; end if;
  if w.employee_signed_at is not null then raise exception 'You have already signed this letter'; end if;
  if coalesce(p_signature, '') = '' or coalesce(trim(p_name), '') = '' then raise exception 'Add your name and signature'; end if;
  update staff_warnings set
    employee_signature_data_url = p_signature,
    employee_signed_name = trim(p_name),
    employee_signed_at = now(),
    employee_signed_how = 'in_app',
    employee_comments = nullif(trim(coalesce(p_comments, '')), ''),
    acknowledged_at = current_date,
    status = case when status = 'issued' then 'acknowledged' else status end,
    updated_at = now()
  where id = p_id;
  perform create_notification(
    w.issued_by, 'hr_letter_signed',
    coalesce((select full_name from profiles where id = w.profile_id), 'An employee') || ' signed their letter',
    coalesce(nullif(w.subject, ''), 'Written warning') || case when coalesce(trim(p_comments), '') <> '' then ' - they added comments' else '' end,
    '/staff.html?id=' || w.profile_id || '&tab=warnings', auth.uid(), 'hr_letter_signed:' || p_id);
end $function$
;

CREATE OR REPLACE FUNCTION public.stc_credit_inc_gst(p_stc numeric, p_client_type text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when p_client_type = 'company'
    then round(coalesce(p_stc, 0) * 1.10, 2)
    else coalesce(p_stc, 0)
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_material_quantity_on_hand()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_material_id uuid;
begin
  v_material_id := coalesce(new.material_id, old.material_id);
  update materials
  set quantity_on_hand = (
    select coalesce(sum(quantity), 0) from material_stock_by_location where material_id = v_material_id
  )
  where id = v_material_id;
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.time_entries_no_job_means_office()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.project_id is null and new.time_category = 'job' then
    new.time_category := 'admin';
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_contract_signed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists (select 1 from onboarding_documents where id = new.document_id and is_contract) then
    update employee_contracts set status = 'signed', updated_at = now()
    where profile_id = new.profile_id and status = 'ready_to_sign';
  end if;
  return new;
exception when others then
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.trg_notify_comment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_post feed_posts%rowtype; v_name text; v_job text;
begin
  select * into v_post from feed_posts where id = new.post_id;
  select full_name into v_name from profiles where id = new.author_id;
  v_job := notif_job_label(v_post.project_id);
  perform create_notification(v_post.author_id, 'comment',
    coalesce(v_name, 'Someone') || ' commented on your post' || case when v_job is not null then ' on ' || v_job else '' end,
    new.message,
    case when v_post.project_id is not null then '/project.html?id=' || v_post.project_id || '&tab=feed' else '/home.html' end,
    new.author_id, 'comment:' || new.id);
  return new;
exception when others then
  raise warning 'notification trigger % failed: %', tg_name, sqlerrm;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.trg_notify_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record;
begin
  if new.direction <> 'inbound' then return new; end if;
  if new.sent_at is not null and new.sent_at < now() - interval '1 day' then return new; end if;
  for r in select id from profiles where active and role in ('admin', 'sales') loop
    perform create_notification(r.id, 'email', 'New email: ' || coalesce(nullif(new.subject, ''), '(no subject)'), 'From ' || coalesce(new.from_address, 'unknown'), '/inbox.html', null, 'email:' || new.id);
  end loop;
  return new;
exception when others then
  raise warning 'notification trigger % failed: %', tg_name, sqlerrm;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.trg_notify_mention()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_post feed_posts%rowtype; v_comment feed_comments%rowtype;
  v_actor uuid; v_msg text; v_name text; v_job text; v_link text;
begin
  select * into v_post from feed_posts where id = new.post_id;
  if new.comment_id is not null then
    select * into v_comment from feed_comments where id = new.comment_id;
    v_actor := v_comment.author_id; v_msg := v_comment.message;
  else
    v_actor := v_post.author_id; v_msg := v_post.message;
  end if;
  select full_name into v_name from profiles where id = v_actor;
  v_job := notif_job_label(v_post.project_id);
  v_link := case when v_post.project_id is not null then '/project.html?id=' || v_post.project_id || '&tab=feed' else '/home.html' end;
  perform create_notification(new.profile_id, 'tag',
    coalesce(v_name, 'Someone') || ' tagged you ' || case when new.comment_id is not null then 'in a comment' else 'in a post' end || case when v_job is not null then ' on ' || v_job else '' end,
    v_msg, v_link, v_actor, 'mention:' || new.id);
  return new;
exception when others then
  raise warning 'notification trigger % failed: %', tg_name, sqlerrm;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.trg_notify_schedule()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_label text;
begin
  if tg_op = 'UPDATE' and old.staff_id = new.staff_id then return new; end if;
  v_label := coalesce(notif_job_label(new.project_id), nullif(new.note, ''), case new.block_type when 'training' then 'Training' when 'office' then 'Office / admin' when 'site_inspection' then 'Site inspection' else 'Booking' end);
  perform create_notification(new.staff_id, 'scheduled',
    'You are booked: ' || v_label,
    to_char(new.assignment_date, 'Dy DD Mon') || ', ' || substr(new.start_time::text, 1, 5) || ' to ' || substr(new.end_time::text, 1, 5),
    '/my-day.html', auth.uid(), 'sched:' || new.id || ':' || new.staff_id);
  return new;
exception when others then
  raise warning 'notification trigger % failed: %', tg_name, sqlerrm;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.trg_notify_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text; v_job text; v_link text; v_creator uuid;
begin
  if new.assigned_to_user_id is not null and not new.completed
     and (tg_op = 'INSERT' or old.assigned_to_user_id is distinct from new.assigned_to_user_id) then
    select full_name into v_name from profiles where id = auth.uid();
    v_job := notif_job_label(new.project_id);
    v_link := case when new.meeting_id is not null then '/meetings.html?id=' || new.meeting_id
                   when new.project_id is not null then '/project.html?id=' || new.project_id
                   else '/tasks.html' end;
    perform create_notification(new.assigned_to_user_id, 'task_assigned',
      coalesce(v_name, 'Someone') || ' gave you a task',
      new.description || case when v_job is not null then ' (' || v_job || ')' else '' end || case when new.due_date is not null then ' - due ' || to_char(new.due_date, 'Dy DD Mon') else '' end,
      v_link, auth.uid(), 'task:' || new.id || ':' || new.assigned_to_user_id);
  end if;

  if tg_op = 'UPDATE' and new.completed and not old.completed and new.meeting_id is not null then
    select created_by into v_creator from meetings where id = new.meeting_id;
    select full_name into v_name from profiles where id = coalesce(new.completed_by, auth.uid());
    perform create_notification(v_creator, 'followup_done',
      coalesce(v_name, 'Someone') || ' finished a meeting follow-up',
      new.description || ' - confirm it was followed up',
      '/meetings.html?id=' || new.meeting_id, coalesce(new.completed_by, auth.uid()), 'fu:' || new.id);
  end if;
  return new;
exception when others then
  raise warning 'notification trigger % failed: %', tg_name, sqlerrm;
  return new;
end $function$
;

