create view public.cost_centres_secure with (security_invoker = false) as
 SELECT id,
    project_id,
    name,
    description,
    sort_order,
    servicem8_job_uuid,
    servicem8_job_status,
        CASE
            WHEN is_pricing_role() THEN markup_percent
            ELSE NULL::numeric
        END AS markup_percent,
        CASE
            WHEN is_pricing_role() THEN quoted_amount
            ELSE NULL::numeric
        END AS quoted_amount,
        CASE
            WHEN is_pricing_role() THEN labour_cost
            ELSE NULL::numeric
        END AS labour_cost,
        CASE
            WHEN is_pricing_role() THEN material_cost
            ELSE NULL::numeric
        END AS material_cost,
        CASE
            WHEN is_pricing_role() THEN invoiced_amount
            ELSE NULL::numeric
        END AS invoiced_amount
   FROM public.cost_centres;

create view public.cost_centre_line_items_secure with (security_invoker = false) as
 SELECT id,
    cost_centre_id,
    description,
    item_type,
    sort_order,
    quantity,
        CASE
            WHEN is_pricing_role() THEN unit_cost
            ELSE NULL::numeric
        END AS unit_cost
   FROM public.cost_centre_line_items;

