        CASE
            WHEN can_view_sensitive_profile_data(id) THEN super_member_number
            ELSE NULL::text
        END AS super_member_number,
        CASE
            WHEN can_view_sensitive_profile_data(id) THEN smsf_abn
            ELSE NULL::text
        END AS smsf_abn,
        CASE
            WHEN can_view_sensitive_profile_data(id) THEN smsf_bank_bsb
            ELSE NULL::text
        END AS smsf_bank_bsb,
        CASE
            WHEN can_view_sensitive_profile_data(id) THEN smsf_bank_account
            ELSE NULL::text
        END AS smsf_bank_account,
        CASE
            WHEN can_view_sensitive_profile_data(id) THEN smsf_esa
            ELSE NULL::text
        END AS smsf_esa,
        CASE
            WHEN can_view_sensitive_profile_data(id) THEN emergency_contact_phone
            ELSE NULL::text
