CREATE TRIGGER notify_email AFTER INSERT ON public.emails FOR EACH ROW EXECUTE FUNCTION public.trg_notify_email();
CREATE TRIGGER notify_comment AFTER INSERT ON public.feed_comments FOR EACH ROW EXECUTE FUNCTION public.trg_notify_comment();
CREATE TRIGGER notify_mention AFTER INSERT ON public.feed_mentions FOR EACH ROW EXECUTE FUNCTION public.trg_notify_mention();
