CREATE TRIGGER trg_sync_material_quantity AFTER INSERT OR DELETE OR UPDATE ON public.material_stock_by_location FOR EACH ROW EXECUTE FUNCTION public.sync_material_quantity_on_hand();
CREATE TRIGGER contract_signed AFTER INSERT ON public.onboarding_document_signatures FOR EACH ROW EXECUTE FUNCTION public.trg_contract_signed();
CREATE TRIGGER trg_guard_profiles_writes BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profiles_writes();
CREATE TRIGGER on_project_stage_change BEFORE INSERT OR UPDATE OF pipeline_stage ON public.projects FOR EACH ROW EXECUTE FUNCTION public.assign_job_number_on_approval();
CREATE TRIGGER notify_schedule AFTER INSERT OR UPDATE OF staff_id ON public.schedule_assignments FOR EACH ROW EXECUTE FUNCTION public.trg_notify_schedule();
CREATE TRIGGER time_entries_category_fix BEFORE INSERT OR UPDATE OF project_id, time_category ON public.time_entries FOR EACH ROW EXECUTE FUNCTION public.time_entries_no_job_means_office();

