-- ============================================================
-- 10. Grants and revokes
--     Supabase default privileges already give anon, authenticated and
--     service_role full table/view/sequence rights and EXECUTE on functions
--     in public. Only the differences from those defaults are listed here.
-- ============================================================

-- profiles: anon and authenticated have no table-wide SELECT. authenticated
-- may only read the non-sensitive columns below (pay rates, bank, tax and
-- address columns are read through profiles_pay_rates_secure and
-- profiles_sensitive_secure). anon gets no column grants.
-- (All other table privileges on profiles stay at the defaults.)
revoke select on table public.profiles from anon, authenticated;
grant select (id, theme, created_at, role, full_name, active, xero_employee_id, mobile_number, notes, photo_url, rate_tier_id, job_title, super_fund_name, super_is_self_managed, emergency_contact_name, emergency_contact_relationship, employment_start_date, employment_type, pay_type, salary_includes_super, has_company_vehicle, onboarding_completed_at, xero_payroll_status, xero_payroll_error, has_probationary_period, onboarding_reissue_reason, onboarding_reissue_note, onboarding_cycle_started_at, home_shortcuts, email_signature, email_signature_include_photo) on table public.profiles to authenticated;
grant insert (email_signature_include_photo), update (email_signature_include_photo) on table public.profiles to authenticated;

-- cost_centres and cost_centre_line_items: column-level SELECT grants for
-- authenticated (left over from the column masking migrations; the table
-- level grant is still full, as in production).
grant select (id, project_id, name, description, sort_order, servicem8_job_uuid, servicem8_job_status) on table public.cost_centres to authenticated;
grant select (id, cost_centre_id, description, item_type, quantity, sort_order) on table public.cost_centre_line_items to authenticated;

-- Functions callable by authenticated and service_role only (not anon, not PUBLIC).
revoke execute on function public.get_active_clock_ins(uuid) from public, anon;
revoke execute on function public.get_monthly_net_summary(integer) from public, anon;
revoke execute on function public.get_overhead_people(text) from public, anon;
revoke execute on function public.get_overhead_rates() from public, anon;
revoke execute on function public.get_project_overheads(uuid) from public, anon;
revoke execute on function public.send_hr_letter(uuid) from public, anon;
revoke execute on function public.sign_hr_letter(uuid, text, text, text) from public, anon;
grant execute on function public.get_active_clock_ins(uuid) to authenticated, service_role;
grant execute on function public.get_monthly_net_summary(integer) to authenticated, service_role;
grant execute on function public.get_overhead_people(text) to authenticated, service_role;
grant execute on function public.get_overhead_rates() to authenticated, service_role;
grant execute on function public.get_project_overheads(uuid) to authenticated, service_role;
grant execute on function public.send_hr_letter(uuid) to authenticated, service_role;
grant execute on function public.sign_hr_letter(uuid, text, text, text) to authenticated, service_role;

-- Internal functions callable by service_role only.
revoke execute on function public.compute_overhead_rates() from public, anon, authenticated;
revoke execute on function public.create_notification(uuid, text, text, text, text, uuid, text) from public, anon, authenticated;
revoke execute on function public.notif_job_label(uuid) from public, anon, authenticated;
revoke execute on function public.overhead_people_calc(text) from public, anon, authenticated;
revoke execute on function public.trg_notify_comment() from public, anon, authenticated;
revoke execute on function public.trg_notify_email() from public, anon, authenticated;
revoke execute on function public.trg_notify_mention() from public, anon, authenticated;
revoke execute on function public.trg_notify_schedule() from public, anon, authenticated;
revoke execute on function public.trg_notify_task() from public, anon, authenticated;
grant execute on function public.compute_overhead_rates() to service_role;
grant execute on function public.create_notification(uuid, text, text, text, text, uuid, text) to service_role;
grant execute on function public.notif_job_label(uuid) to service_role;
grant execute on function public.overhead_people_calc(text) to service_role;
grant execute on function public.trg_notify_comment() to service_role;
grant execute on function public.trg_notify_email() to service_role;
grant execute on function public.trg_notify_mention() to service_role;
grant execute on function public.trg_notify_schedule() to service_role;
grant execute on function public.trg_notify_task() to service_role;

-- All other 36 public functions keep the default: EXECUTE for PUBLIC, anon,
-- authenticated and service_role.

-- ============================================================
-- 11. Storage buckets (config only, never objects)
-- ============================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('email-attachments', 'email-attachments', false, null, null),
  ('knowledge-files', 'knowledge-files', false, null, null),
  ('lead-uploads', 'lead-uploads', false, null, null),
  ('meeting-audio', 'meeting-audio', false, null, null),
  ('project-documents', 'project-documents', false, null, null),
  ('proposal-photos', 'proposal-photos', true, null, null),
  ('site-photos', 'site-photos', true, null, null),
  ('staff-files', 'staff-files', false, null, null)
on conflict (id) do nothing;

-- ============================================================
-- 12. pg_cron: the cron extension is not installed on the live project, so
--     there are no cron.job rows to reproduce. (Scheduled work runs outside
--     the database.)
-- ============================================================

-- ============================================================
-- 13. Realtime publication membership
-- ============================================================

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (
       select 1 from pg_publication_tables
       where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'notifications'
     ) then
    alter publication supabase_realtime add table public.notifications;
  end if;
end
$$;
